begin;
create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public, pg_catalog;
select plan(4);
select lives_ok($test$ select private.assert_learner_profile_envelope('{"exportedAt":"2026-09-28T01:00:00.000Z","integrity":{"algorithm":"SHA-256","byteLength":976,"payloadSha256":"RCeuBxNXqAWglw9q1DbGIsmmu66sXuTqk3olhQwveHc"},"profile":{"activityLog":[],"anki":{},"cityProgress":{"maxLevelIndex":0},"config":{"ankiEnabled":true,"channelShelfOrder":[],"channelVideoFormats":{},"channels":[],"includeShorts":true,"locale":"en","removedChannelIds":[],"removedDefaultChannelIds":[],"weeklyGoalHours":4},"learnerProfile":{"createdAt":"2026-09-28T01:00:00.000Z","languages":["french"],"level":"beginner","selectedChannelCatalogIds":[],"updatedAt":"2026-09-28T01:00:00.000Z"},"noAnkiFrequentUserPrompt":{"respondedAt":null,"response":null},"onboarding":{"introSeenAt":"2026-09-28T01:00:00.000Z","levelUpGuidanceShownAt":null,"recommendationsAppliedAt":null,"setupCompleted":true,"setupCompletedAt":"2026-09-28T01:00:00.000Z","walkthroughCompleted":false,"walkthroughCompletedAt":null},"videos":{}},"schema":"edenia-portable-learner-profile","version":1}'::jsonb) $test$, 'old portable profiles still validate');
select lives_ok($test$ select private.assert_initial_learner_profile_envelope('{"exportedAt":"2026-09-28T01:00:00.000Z","integrity":{"algorithm":"SHA-256","byteLength":1050,"payloadSha256":"IxFU0jWm9CCHpUvDIeX3AATPsx3QClHwInMFyGPS8PQ"},"profile":{"activityLog":[],"anki":{},"cityProgress":{"maxLevelIndex":0},"config":{"ankiEnabled":true,"channelShelfOrder":[],"channelVideoFormats":{},"channels":[],"includeShorts":true,"locale":"en","removedChannelIds":[],"removedDefaultChannelIds":[],"weeklyGoalHours":4},"learnerProfile":{"createdAt":"2026-09-28T01:00:00.000Z","languages":["french"],"level":"beginner","selectedChannelCatalogIds":[],"updatedAt":"2026-09-28T01:00:00.000Z"},"noAnkiFrequentUserPrompt":{"respondedAt":null,"response":null},"onboarding":{"introSeenAt":"2026-09-28T01:00:00.000Z","levelUpGuidanceShownAt":null,"recommendationsAppliedAt":null,"setupCompleted":true,"setupCompletedAt":"2026-09-28T01:00:00.000Z","walkthroughCompleted":false,"walkthroughCompletedAt":null},"townEconomy":{"mode":"starter","purchases":{},"rewards":{},"version":1},"videos":{}},"schema":"edenia-portable-learner-profile","version":1}'::jsonb) $test$, 'empty starter economy can be created with a signed-in profile');
select lives_ok($test$ select private.assert_learner_profile_envelope('{"exportedAt":"2026-09-28T01:00:00.000Z","integrity":{"algorithm":"SHA-256","byteLength":1138,"payloadSha256":"lxHV3bFZpZn4KJbjYNK8oDiueRplOBvS7u0dYfAceD8"},"profile":{"activityLog":[],"anki":{},"cityProgress":{"maxLevelIndex":0},"config":{"ankiEnabled":true,"channelShelfOrder":[],"channelVideoFormats":{},"channels":[],"includeShorts":true,"locale":"en","removedChannelIds":[],"removedDefaultChannelIds":[],"weeklyGoalHours":4},"learnerProfile":{"createdAt":"2026-09-28T01:00:00.000Z","languages":["french"],"level":"beginner","selectedChannelCatalogIds":[],"updatedAt":"2026-09-28T01:00:00.000Z"},"noAnkiFrequentUserPrompt":{"respondedAt":null,"response":null},"onboarding":{"introSeenAt":"2026-09-28T01:00:00.000Z","levelUpGuidanceShownAt":null,"recommendationsAppliedAt":null,"setupCompleted":true,"setupCompletedAt":"2026-09-28T01:00:00.000Z","walkthroughCompleted":false,"walkthroughCompletedAt":null},"townEconomy":{"mode":"starter","purchases":{"garden-flower-1":15},"rewards":{"video:lesson:2026-09-28T01:00:00.000Z":{"baseline":0,"seconds":600}},"version":1},"videos":{}},"schema":"edenia-portable-learner-profile","version":1}'::jsonb) $test$, 'purchase and reward receipts pass cloud validation together');
select throws_ok($test$ select private.assert_initial_learner_profile_envelope('{"exportedAt":"2026-09-28T01:00:00.000Z","integrity":{"algorithm":"SHA-256","byteLength":1138,"payloadSha256":"lxHV3bFZpZn4KJbjYNK8oDiueRplOBvS7u0dYfAceD8"},"profile":{"activityLog":[],"anki":{},"cityProgress":{"maxLevelIndex":0},"config":{"ankiEnabled":true,"channelShelfOrder":[],"channelVideoFormats":{},"channels":[],"includeShorts":true,"locale":"en","removedChannelIds":[],"removedDefaultChannelIds":[],"weeklyGoalHours":4},"learnerProfile":{"createdAt":"2026-09-28T01:00:00.000Z","languages":["french"],"level":"beginner","selectedChannelCatalogIds":[],"updatedAt":"2026-09-28T01:00:00.000Z"},"noAnkiFrequentUserPrompt":{"respondedAt":null,"response":null},"onboarding":{"introSeenAt":"2026-09-28T01:00:00.000Z","levelUpGuidanceShownAt":null,"recommendationsAppliedAt":null,"setupCompleted":true,"setupCompletedAt":"2026-09-28T01:00:00.000Z","walkthroughCompleted":false,"walkthroughCompletedAt":null},"townEconomy":{"mode":"starter","purchases":{"garden-flower-1":15},"rewards":{"video:lesson:2026-09-28T01:00:00.000Z":{"baseline":0,"seconds":600}},"version":1},"videos":{}},"schema":"edenia-portable-learner-profile","version":1}'::jsonb) $test$, '22023', 'Initial learner profile economy is invalid', 'first profile cannot inherit purchased items or study rewards');
select * from finish();
rollback;
